import {isBuildingLotRoot,updateBuildingLot} from './building-lots.js?v=architecture-collection-44';
import {tileIndex} from './city-grid.js?v=architecture-collection-44';
// Manual pp.99,124: agricultural land and education-driven industrial change.
export const industrialJobs=t=>t.industry==='farm'?(t.farmRoot===tileIndex(t)&&t.level?12+Math.floor((Math.max(9,t.farmSize||9)-9)/3):0):([0,1,3,8][t.level]||0)*12;
export const industryPollution=t=>t.industry==='clean'?.1:t.industry==='farm'?.03:1;
export const cleanThreshold=c=>Math.max(40,80-((c.startYear||1950)+Math.floor(c.month/12)-1900)*.175)-(c.civic.ordinances.cleanWater?10:0);
const chance=(c,t,offset=0)=>((Math.imul(t.x+37,73856093)^Math.imul(t.y+offset+17,19349663)^Math.imul(c.month+1,83492791)^c.seed)>>>0)/4294967296;
export const MAX_FARM_SIDE=8;
export function farmBounds(members){const xs=members.map(t=>t.x),ys=members.map(t=>t.y);return{x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs)+1,height:Math.max(...ys)-Math.min(...ys)+1};}
export function normalizeIndustry(c){const groups=new Map();for(const t of c.tiles){t.farmSize=0;if(t.type!=='industrial'||!t.level&&!t.historicalLevel&&!t.abandonedLevel){t.industry='dirty';t.farmRoot=null;continue;}if(t.industry!=='farm'){t.farmRoot=null;continue;}if(!groups.has(t.farmRoot))groups.set(t.farmRoot,[]);groups.get(t.farmRoot).push(t);}for(const [root,members] of groups){const r=c.tiles[root],b=farmBounds(members),valid=r&&r.industry==='farm'&&r.level===1&&r.x===b.x&&r.y===b.y&&b.width>=3&&b.height>=3&&b.width<=MAX_FARM_SIDE&&b.height<=MAX_FARM_SIDE&&members.length===b.width*b.height&&members.every(t=>t.level===1&&t.density===1&&!t.radiation&&!t.rubble);for(const t of members){if(valid)t.farmSize=members.length;else{t.industry='dirty';t.farmRoot=null;}}}}
function ruralTile(t,root){return t.type==='industrial'&&!t.level&&!t.historicalLevel&&t.density===1&&!t.radiation&&!t.rubble&&!t.fire&&t.elevation===root.elevation&&t.landValue<=60&&t.airPollution<=15&&t.waterPollution<=15;}
function rectangle(c,t,width,height,owned=null){const n=Math.sqrt(c.tiles.length);if(t.x+width>n||t.y+height>n)return null;const members=[];for(let y=t.y;y<t.y+height;y++)for(let x=t.x;x<t.x+width;x++){const u=c.tiles[y*n+x];if(!(owned!==null&&u.industry==='farm'&&u.farmRoot===owned)&&!ruralTile(u,t))return null;members.push(u);}const road=(x,y)=>x>=0&&y>=0&&x<n&&y<n&&(c.tiles[y*n+x].type==='road'||c.tiles[y*n+x].highway),sides=[Array.from({length:width},(_,k)=>road(t.x+k,t.y-1)),Array.from({length:height},(_,k)=>road(t.x+width,t.y+k)),Array.from({length:width},(_,k)=>road(t.x+k,t.y+height)),Array.from({length:height},(_,k)=>road(t.x-1,t.y+k))];return sides.filter(s=>s.some(Boolean)).length<3?members:null;}
export function farmCandidate(c,t){if(!t.powered||!t.access)return null;let width=3,height=3,members=rectangle(c,t,width,height);if(!members)return null;while(width<MAX_FARM_SIDE||height<MAX_FARM_SIDE){const horizontal=width<MAX_FARM_SIDE?rectangle(c,t,width+1,height):null,vertical=height<MAX_FARM_SIDE?rectangle(c,t,width,height+1):null;if(horizontal&&(!vertical||width<=height)){width++;members=horizontal;}else if(vertical){height++;members=vertical;}else break;}return members;}
function reserveFarmJobs(c,amount){const cap=c.stats.economicCaps?.industrial;if(!cap)return true;if(cap.remaining<amount)return false;cap.population+=amount;cap.remaining-=amount;return true;}
export function expandFarms(c){if(c.month%3)return 0;const roots=c.tiles.filter(t=>t.industry==='farm'&&t.farmRoot===t.y*Math.sqrt(c.tiles.length)+t.x);let added=0;for(const root of roots){if(root.age<6||!root.powered||!root.access)continue;const owned=root.farmRoot,members=c.tiles.filter(t=>t.industry==='farm'&&t.farmRoot===owned);if(members.some(t=>t.landValue>68||t.airPollution>25||t.waterPollution>25||t.fire))continue;const b=farmBounds(members),horizontal=b.width<MAX_FARM_SIDE?rectangle(c,root,b.width+1,b.height,owned):null,vertical=b.height<MAX_FARM_SIDE?rectangle(c,root,b.width,b.height+1,owned):null,next=horizontal&&(!vertical||b.width<=b.height)?horizontal:vertical;if(!next||!reserveFarmJobs(c,Math.floor((next.length-9)/3)-Math.floor((members.length-9)/3)))continue;for(const t of next)if(t.industry!=='farm'){t.industry='farm';t.farmRoot=owned;t.level=1;t.abandonedLevel=0;t.age=0;t.stress=0;added++;}}if(added)normalizeIndustry(c);return added;}
export function advanceIndustry(c){normalizeIndustry(c);const fieldsAdded=expandFarms(c);let farms=0,clean=0;for(const t of c.tiles){if(t.type!=='industrial'||t.historicalLevel||!isBuildingLotRoot(c,t))continue;if(t.industry==='farm'){if(t.landValue>68||t.airPollution>25||t.waterPollution>25){const root=t.farmRoot;for(const u of c.tiles)if(u.industry==='farm'&&u.farmRoot===root){u.industry='dirty';u.farmRoot=null;}}continue;}if(!t.level&&(c.stats.marketDemandBase?.industrial??c.stats.demand.industrial)+(t.marketDemandBonus||0)>0&&chance(c,t)<.25){const members=farmCandidate(c,t);if(members&&reserveFarmJobs(c,12+Math.floor((members.length-9)/3))){for(const u of members){u.industry='farm';u.farmRoot=tileIndex(t);u.level=1;u.abandonedLevel=0;u.age=0;u.stress=0;}farms++;continue;}}if(t.level&&t.industry!=='clean'&&t.powered&&t.access&&t.age>=6&&c.civic.education>=cleanThreshold(c)&&chance(c,t,97)<.2){updateBuildingLot(c,t,{industry:'clean'});clean++;}}normalizeIndustry(c);return{farms,clean,fieldsAdded};}
export function industryStats(c){return{farms:c.tiles.filter(t=>t.industry==='farm'&&t.farmRoot===tileIndex(t)).length,farmFields:c.tiles.filter(t=>t.industry==='farm').length,cleanIndustry:c.tiles.filter(t=>t.type==='industrial'&&t.level&&t.industry==='clean'&&isBuildingLotRoot(c,t)).length};}
